<div class="chain-block"><div class="card-choice-tab-block"><div class="card-choice-tab-item" :class="choicedTab===item?'card-choice-tab-item-choiced':''" v-for="(item,index) in props.cardChoiceTabList" @click="tabClick(item)">{{item}}</div></div><div class="battle-chain-cards" v-if="choicedTab==='对方手卡'"><div class="battle-chain-card" :class="getChoicedClass('botHand',index)" v-for="(card,index) in allMes.allMesBot.handCardList" @click="botHandChoicedClick(index)"><div class="battle-chain-card-name">{{card.name}}</div></div><div style="clear:both;"></div></div><div class="battle-chain-cards" v-if="choicedTab==='对方盖卡'"><div class="battle-chain-card" :class="getChoicedClass('botGround',index)" v-for="(card,index) in allMes.allMesBot.cardGroundList" @click="botGroundChoicedClick(index)"><div class="battle-chain-card-name">???</div></div><div style="clear:both;"></div></div><div class="battle-chain-cards" v-if="choicedTab==='我方手卡'"><div class="battle-chain-card" :class="getChoicedClass('myHand',index)" v-for="(card,index) in allMes.allMesMy.handCardList" @click="myHandChoicedClick(index)"><div class="battle-chain-card-name">{{card.name}}</div></div><div style="clear:both;"></div></div><div class="battle-chain-cards" v-if="choicedTab==='我方盖卡'"><div class="battle-chain-card" :class="getChoicedClass('myGround',index)" v-for="(card,index) in allMes.allMesMy.cardGroundList" @click="myGroundChoicedClick(index)"><div class="battle-chain-card-name">{{card.name}}</div></div><div style="clear:both;"></div></div><div class="battle-chain-cards" v-if="choicedTab==='墓地'"><div class="battle-chain-card" :class="getChoicedClass('cardUsedList',index)" v-for="(card,index) in allMes.cardUsedList" @click="cardUsedListChoicedClick(index)" v-show="cardUsedShow(card)"><div class="battle-chain-card-name">{{card.name}}</div></div><div style="clear:both;"></div></div><div class="battle-chain-cards" v-if="choicedTab==='墓地(重整旗鼓)'"><div class="battle-chain-card" :class="getChoicedClass('cardUsedListCZQG',index)" v-for="(card,index) in cardUsedListCZQG" @click="cardUsedListCZQGChoicedClick(index)" v-show="cardUsedShow(card)"><div class="battle-chain-card-name">{{card.name}}</div></div><div style="clear:both;"></div></div><div class="battle-chain-cards" v-if="choicedTab==='墓地(黑魔法)'"><div class="battle-chain-card" :class="getChoicedClass('cardUsedListBlackMagic',index)" v-for="(card,index) in cardUsedListBlackMagic" @click="cardUsedListBlackMagicChoicedClick(index)" v-show="cardUsedShow(card)"><div class="battle-chain-card-name">{{card.name}}</div></div><div style="clear:both;"></div></div><div class="battle-chain-title">已选</div><div class="battle-chain-cards" v-if="choiceCardList.length&gt;0"><div class="battle-chain-card" v-for="(card,index) in choiceCardList" @click="delChoicedList(card.type,card.index)"><div class="battle-chain-card-name">{{getChoicedCardListName(card)}}</div></div><div style="clear:both;"></div></div><div class="battle-chain-buttons"> <el-button class="battle-chain-button" type="default" :disabled="choiceCardList.length===0" @click="makeSure()">确认</el-button><div style="clear:both;"></div></div></div>